c=d.pop('checks');print(json.dumps(d))
for k,v in c.items():
  o=v.get('observed');
  if isinstance(o,dict):
    for kk in ('failed_first_try','failed_after_retries'):
      if kk in o: o[kk]=len(o[kk])
  print(k,json.dumps(v))"; done

